ALTER TABLE public.basis_edge
    ADD CONSTRAINT ck_basis_edge_dependent_kind CHECK (dependent_kind IN ('ENTRY')),
    ADD CONSTRAINT ck_basis_edge_source_kind CHECK (source_kind IN ('ENTRY')),
    ADD CONSTRAINT sfk_basis_edge_account FOREIGN KEY (account_id) REFERENCES public.account(id) ON DELETE RESTRICT;

ALTER TABLE public.basis_edge ENABLE ROW LEVEL SECURITY;
CREATE POLICY basis_edge_owner ON public.basis_edge TO hephaestus_app
    USING (account_id = public.current_owner_account())
    WITH CHECK (account_id = public.current_owner_account());

-- The function names its tables with the schema: person_row_sweep fires these triggers with an empty search path.
CREATE FUNCTION public.basis_entry_removed() RETURNS trigger
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
    AS $$
BEGIN
    INSERT INTO public.source_tombstone (workspace_id, source_kind, source_id, kind)
    VALUES (NEW.workspace_id, 'ENTRY', NEW.id, 'DELETED_SOURCE')
    ON CONFLICT DO NOTHING;
    RETURN NULL;
END
$$;

CREATE FUNCTION public.basis_entry_moved() RETURNS trigger
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
    AS $$
BEGIN
    UPDATE public.basis_edge SET account_id = NEW.account_id
    WHERE dependent_kind = 'ENTRY' AND dependent_id = NEW.id AND account_id = OLD.account_id;
    RETURN NULL;
END
$$;

CREATE FUNCTION public.basis_entries_deleted() RETURNS trigger
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp
    AS $$
BEGIN
    DELETE FROM public.source_tombstone t USING gone
    WHERE t.workspace_id = gone.workspace_id AND t.source_kind = 'ENTRY' AND t.source_id = gone.id;
    DELETE FROM public.basis_edge e USING gone
    WHERE e.dependent_kind = 'ENTRY' AND e.dependent_id = gone.id;
    RETURN NULL;
END
$$;

CREATE TRIGGER conversation_entry_basis_removed
    AFTER UPDATE OF redacted_at ON public.conversation_entry
    FOR EACH ROW WHEN (OLD.redacted_at IS NULL AND NEW.redacted_at IS NOT NULL)
    EXECUTE FUNCTION public.basis_entry_removed();

CREATE TRIGGER conversation_entry_basis_moved
    AFTER UPDATE OF account_id ON public.conversation_entry
    FOR EACH ROW WHEN (OLD.account_id IS DISTINCT FROM NEW.account_id)
    EXECUTE FUNCTION public.basis_entry_moved();

CREATE TRIGGER conversation_entry_basis_deleted
    AFTER DELETE ON public.conversation_entry
    REFERENCING OLD TABLE AS gone
    FOR EACH STATEMENT EXECUTE FUNCTION public.basis_entries_deleted();
